// Omniflow batch 1461 - ADMIN AI CONTROL CENTER + AGENT PERMISSIONS +
// AGENT VERSIONING/ROLLBACK (MASTER-UPGRADE build-order 15 + 16a).
// Audit-first: reuses agents, actions registry (risk + approvals),
// platform_settings, ai_usage/ai_audit/escalations/notify - no new engine.
// CP: platform_settings group ai (kill_switch / autonomy_cap /
// daily_call_cap, env fallback, cached fail-soft ai_controls());
// admin_providers ai whitelist + numeric cap; portal_ai_usage.gate +
// portal_llm gated chat_json (no HTTP when paused / capped, owner notified
// once a day); portal_brain platform_controls + effective_autonomy +
// draft-only personas (agent_draft_only handoff) + settings.platform;
// portal_agents permissions (allowed_actions / max_risk / can_auto_reply,
// permits()) + portal_agent_versions append-only history + rollback;
// portal_actions.execute(agent=) -> denied before the approval gate; brain
// tools + workflow action steps pass their persona; NEW admin_ai.py
// (GET /admin/ai/overview, POST /admin/ai/clients/<id>/autonomy with
// audit + owner notification); app.py blueprint + URL-map dispatch net
// (every aux route reachable: public checkout/store/voice, admin
// providers/email/weekly report/AI control - HANDOFF 202).
// Web: /admin/ai-control page + sidebar entry, admin BFF overview +
// autonomy override, providers route accepts group ai,
// admin-control-plane.ts client; portal agents BFF permissions
// (agent-permissions.ts), versions + rollback routes, portal.ts types +
// calls, Team > Agents editor Permissions section + Version history /
// Restore, BrainCard platform notice.
// Rig: NEW test_admin_ai (51) + NEW test_app_boot (31); test_agents 76,
// test_actions 24, test_brain 117, test_workflows 160, test_providers ai
// group; run_sweep --mirror-only + mirror_p13. Docs: HANDOFF 201/202 +
// UPGRADE_DECISIONS + gap analysis + audit brief.
// LAYOUT LAW (202): CP files are written to BOTH omniflow-backend-patch/
// (website-side mirror) AND OmniFlow-Control-Plane/ (the CP repo that
// Vercel deploys). Run from the website repo root (bot root).
// Whole-file marker-guarded ops (backup on drift, .pre_cc.bak);
// idempotent; dir-conflicts quarantined; CP files py_compile-guarded.
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
const BACKUP_TAG = ".pre_cc.bak";
let applied = 0, already = 0, warnings = 0;
if (!fs.existsSync("OmniFlow-Control-Plane") || !fs.statSync("OmniFlow-Control-Plane").isDirectory()) {
  console.log("X Run this from the website repo root (bot root) - the folder that contains OmniFlow-Control-Plane/. Nothing was written.");
  process.exit(1);
}
function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
      fs.unlinkSync(repoPath);
      console.log("X " + repoPath + " FAILED to compile - not written");
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("X " + repoPath + " FAILED to compile - old copy restored");
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
writeNewRepair("omniflow-backend-patch/platform_settings.py", "def ai_controls(", false,
    "\"\"\"Platform-level settings store (admin-panel managed provider config).\n\nOne tiny table - platform_settings(key TEXT PRIMARY KEY, value TEXT,\nupdated_at) - holds everything the owner types into the admin panel's\nIntegrations page: SMTP/Brevo email credentials, the LLM engine config,\nthe AI feature switches and the future-channel keys (voice, video,\npayments, phone verification, the WhatsApp E2E test number).\n\nDesign laws:\n- STANDARD LIBRARY ONLY for the readers (portal_llm imports this inside\n  the ingest hot path; flask lives in admin_providers, not here).\n- Fail-soft: any read error -> None, and the caller falls back to its\n  environment variable (env-config adapters stay the safety net).\n- Secrets are stored as-is in the database and masked by the admin API;\n  the readers here are server-side only.\n- A 30-second TTL cache keeps the ingest loop from hammering the\n  database; every PUT invalidates it on the instance that wrote.\n\"\"\"\n\nimport time\n\ntry:  # pragma: no cover - always available in the Control Plane image\n    import portal_db\nexcept Exception:  # pragma: no cover - tests may inject a stub\n    portal_db = None\n\nTABLE = \"platform_settings\"\nCACHE_TTL_SECONDS = 30.0\n\n_DDL_READY = False\n_cache = {}\n_cache_at = 0.0\n\ndef _ddl() -> str:\n    \"\"\"Built lazily so importing this module never touches portal_db.\"\"\"\n    return (\n        \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(TABLE) + \" (\"\n        \" key TEXT PRIMARY KEY,\"\n        \" value TEXT NOT NULL DEFAULT '',\"\n        \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\"\n        \")\"\n    )\n\n# group -> the exact keys the admin API accepts for that group.\nGROUP_KEYS = {\n    \"email\": [\"provider\", \"smtp_host\", \"smtp_port\", \"smtp_user\",\n              \"smtp_password\", \"smtp_from\", \"brevo_api_key\", \"reports_to\"],\n    \"llm\": [\"base_url\", \"api_key\", \"model\", \"prices_json\"],\n    \"flags\": [\"true_sentiment\", \"kb_autodraft\", \"phone_verification\"],\n    \"voice\": [\"provider\", \"account_sid\", \"auth_token\", \"from_number\"],\n    \"video\": [\"provider\", \"api_key\", \"zoom_account_id\",\n              \"zoom_client_id\", \"zoom_client_secret\"],\n    \"payments\": [\"provider\", \"publishable_key\", \"secret_key\",\n                 \"webhook_secret\"],\n    \"whatsapp_e2e\": [\"live_number\"],\n    \"stt\": [\"api_key\", \"base_url\", \"model\"],\n    # Platform AI controls (admin AI Control Center): a global pause, the\n    # highest autonomy any workspace may run at, and a per-workspace daily\n    # LLM call cap (0 = unlimited). Env fallbacks: OF_AI_KILL_SWITCH,\n    # OF_AI_AUTONOMY_CAP, OF_AI_DAILY_CALL_CAP.\n    \"ai\": [\"kill_switch\", \"autonomy_cap\", \"daily_call_cap\"],\n}\n\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\n\nSECRET_HINTS = (\"password\", \"api_key\", \"token\", \"secret\")\n\n\ndef _key(group: str, name: str) -> str:\n    return group + \".\" + name\n\n\ndef _ensure(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_ddl())\n    _DDL_READY = True\n\n\ndef invalidate_cache() -> None:\n    \"\"\"Drop the TTL cache (called after every successful PUT).\"\"\"\n    global _cache_at\n    _cache.clear()\n    _cache_at = 0.0\n\n\ndef get_setting(key: str, default=None):\n    \"\"\"One setting as TEXT; default on any error (fail-soft).\"\"\"\n    global _cache, _cache_at\n    if portal_db is None:\n        return default\n    now = time.monotonic()\n    if _cache and (now - _cache_at) < CACHE_TTL_SECONDS:\n        if key in _cache:\n            return _cache[key]\n        return default\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                _ensure(cur)\n                cur.execute(\n                    \"SELECT key, value FROM \" + portal_db._q(TABLE)\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n        _cache = {str(r[\"key\"]): str(r[\"value\"] or \"\") for r in rows}\n        _cache_at = time.monotonic()\n    except Exception:\n        _cache.clear()\n        _cache_at = 0.0\n        return default\n    return _cache.get(key, default)\n\n\ndef get_group(group: str) -> dict:\n    \"\"\"Every stored key of one group as {name: value} (no defaults).\"\"\"\n    prefix = group + \".\"\n    out = {}\n    if portal_db is None:\n        return out\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                _ensure(cur)\n                cur.execute(\n                    \"SELECT key, value FROM \" + portal_db._q(TABLE)\n                    + \" WHERE key LIKE %s\",\n                    (prefix + \"%\",),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception:\n        return out\n    for row in rows:\n        out[str(row[\"key\"])[len(prefix):]] = str(row[\"value\"] or \"\")\n    return out\n\n\ndef put_group(cur, group: str, values: dict) -> None:\n    \"\"\"Upsert one group inside the CALLER's transaction (admin PUT).\n\n    The caller owns auth, whitelist filtering, the audit row and the\n    commit; this only writes the key/value pairs.\n    \"\"\"\n    prefix = group + \".\"\n    for name, value in values.items():\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(TABLE) +\n            \" (key, value, updated_at) VALUES (%s, %s, NOW())\"\n            \" ON CONFLICT (key) DO UPDATE SET\"\n            \" value = EXCLUDED.value, updated_at = NOW()\",\n            (prefix + name, str(value)),\n        )\n\n\ndef _env(name: str, default: str = \"\") -> str:\n    import os\n    return os.environ.get(name, default).strip()\n\n\ndef llm_config() -> dict:\n    \"\"\"Effective LLM config: admin panel first, env fallback.\n\n    enabled keeps the env kill switch: OF_LLM_ENABLED explicitly off\n    wins over a stored key.\n    \"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"llm\")\n    except Exception:\n        stored = {}\n    env_enabled = _env(\"OF_LLM_ENABLED\", \"1\").lower() not in (\n        \"0\", \"false\", \"no\", \"off\")\n    api_key = str(stored.get(\"api_key\") or _env(\"OF_LLM_API_KEY\", \"\"))\n    return {\n        \"base_url\": (str(stored.get(\"base_url\") or \"\")\n                     or _env(\"OF_LLM_BASE_URL\",\n                             \"https://api.openai.com/v1\")).rstrip(\"/\"),\n        \"api_key\": api_key,\n        \"model\": str(stored.get(\"model\") or \"\")\n                 or _env(\"OF_LLM_MODEL\", \"gpt-4o-mini\"),\n        \"enabled\": bool(api_key) and env_enabled,\n    }\n\n\ndef ai_controls() -> dict:\n    \"\"\"Effective platform AI controls: admin panel first, env fallback.\n\n    {kill_switch: bool, autonomy_cap: off|suggest|auto,\n     daily_call_cap: int (0 = unlimited), source: panel|env|default}\n    Fail-soft: any storage problem yields the permissive defaults. Reads\n    go through get_setting (30 s TTL cache) because the LLM gate consults\n    this on EVERY call - never an extra round trip per call.\n    \"\"\"\n    stored = {}\n    try:\n        for name in GROUP_KEYS[\"ai\"]:\n            stored[name] = str(get_setting(\"ai.\" + name, \"\") or \"\")\n    except Exception:\n        stored = {}\n    source = \"default\"\n    kill_raw = str(stored.get(\"kill_switch\") or \"\")\n    if kill_raw:\n        source = \"panel\"\n    else:\n        kill_raw = _env(\"OF_AI_KILL_SWITCH\", \"\")\n        if kill_raw:\n            source = \"env\"\n    cap_raw = str(stored.get(\"autonomy_cap\") or \"\").strip().lower()\n    if cap_raw and source == \"default\":\n        source = \"panel\"\n    if not cap_raw:\n        cap_raw = _env(\"OF_AI_AUTONOMY_CAP\", \"\").lower()\n        if cap_raw and source == \"default\":\n            source = \"env\"\n    if cap_raw not in AUTONOMY_LEVELS:\n        cap_raw = \"auto\"\n    daily_raw = str(stored.get(\"daily_call_cap\") or \"\").strip()\n    if daily_raw and source == \"default\":\n        source = \"panel\"\n    if not daily_raw:\n        daily_raw = _env(\"OF_AI_DAILY_CALL_CAP\", \"\")\n        if daily_raw and source == \"default\":\n            source = \"env\"\n    try:\n        daily_cap = max(0, int(daily_raw or 0))\n    except (TypeError, ValueError):\n        daily_cap = 0\n    return {\n        \"kill_switch\": kill_raw.strip().lower() in (\"on\", \"1\", \"true\", \"yes\"),\n        \"autonomy_cap\": cap_raw,\n        \"daily_call_cap\": daily_cap,\n        \"source\": source,\n    }\n\n\ndef video_config() -> dict:\n    \"\"\"Effective video-provider config: admin panel first, env fallback.\"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"video\")\n    except Exception:\n        stored = {}\n    def pick(name, env, default=\"\"):\n        return str(stored.get(name) or \"\").strip() or _env(env, default)\n    provider = (str(stored.get(\"provider\") or \"\").strip().lower()\n                or _env(\"OF_VIDEO_PROVIDER\", \"whereby\"))\n    return {\n        \"provider\": provider,\n        \"api_key\": str(stored.get(\"api_key\") or \"\")\n                   or os_secret_env(\"OF_VIDEO_API_KEY\"),\n        \"zoom_account_id\": pick(\"zoom_account_id\", \"OF_ZOOM_ACCOUNT_ID\"),\n        \"zoom_client_id\": pick(\"zoom_client_id\", \"OF_ZOOM_CLIENT_ID\"),\n        \"zoom_client_secret\": str(stored.get(\"zoom_client_secret\") or \"\")\n                              or os_secret_env(\"OF_ZOOM_CLIENT_SECRET\"),\n    }\n\n\ndef smtp_config() -> dict:\n    \"\"\"Effective email config: admin panel first, env fallback.\"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"email\")\n    except Exception:\n        stored = {}\n    def pick(name, env, default=\"\"):\n        return str(stored.get(name) or \"\").strip() or _env(env, default)\n    provider = (str(stored.get(\"provider\") or \"\").strip().lower()\n                or (\"brevo\" if _env(\"BREVO_API_KEY\") else \"smtp\"))\n    return {\n        \"provider\": provider,\n        \"smtp_host\": pick(\"smtp_host\", \"SMTP_HOST\"),\n        \"smtp_port\": pick(\"smtp_port\", \"SMTP_PORT\", \"587\"),\n        \"smtp_user\": pick(\"smtp_user\", \"SMTP_USER\"),\n        \"smtp_password\": str(stored.get(\"smtp_password\") or \"\")\n                         or os_secret_env(\"SMTP_PASSWORD\"),\n        \"smtp_from\": pick(\"smtp_from\", \"SMTP_FROM\",\n                          \"OmniFlow <no-reply@omniflow.app>\"),\n        \"brevo_api_key\": str(stored.get(\"brevo_api_key\") or \"\")\n                         or os_secret_env(\"BREVO_API_KEY\"),\n        \"reports_to\": pick(\"reports_to\", \"OMNIFLOW_REPORTS_TO\"),\n    }\n\n\ndef os_secret_env(name: str) -> str:\n    \"\"\"Secret env fallback (os.environ read kept out of the hot path).\"\"\"\n    import os\n    return os.environ.get(name, \"\")\n\n\ndef flag(name: str) -> bool:\n    \"\"\"AI/feature switch state; every switch defaults OFF.\"\"\"\n    try:\n        raw = str(get_setting(\"flags.\" + name, \"\") or \"\").strip().lower()\n    except Exception:\n        return False\n    return raw in (\"on\", \"1\", \"true\", \"yes\")\n\n\ndef stt_config() -> dict:\n    \"\"\"Effective speech-to-text config: admin panel first, env fallback.\n\n    portal_media owns the base/model defaults (OpenAI-compatible whisper\n    endpoint); this only resolves what the owner saved (or the env).\n    \"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"stt\")\n    except Exception:\n        stored = {}\n    return {\n        \"api_key\": str(stored.get(\"api_key\")\n                       or _env(\"OMNIFLOW_STT_API_KEY\", \"\")),\n        \"base_url\": str(stored.get(\"base_url\")\n                        or _env(\"OMNIFLOW_STT_BASE\", \"\")),\n        \"model\": str(stored.get(\"model\")\n                     or _env(\"OMNIFLOW_STT_MODEL\", \"\")),\n    }\n");
